// 시험용 참고 파일: libwebp(PIL 13, 브라우저와 같은 인코더)가 만든 작은 손실 WebP 와 libwebp 로 푼 PNG (base64).
// 직접 짠 VP8 디코더가 libwebp 와 같은 그림을 내는지 (색차 늘리기 반올림 차이만) 확인.
using ComicPadNative.Modules.Media;

namespace ComicPadNative.Modules.Gaps;

public static partial class GapsTest
{
    const string RefOddWebp = "";
    const string RefOddPng = "";
    const string RefAlphaWebp = "";
    const string RefAlphaPng = "";

    static void TestVp8Embedded()
    {
        foreach (var (name, webp, png) in new[] { ("37×23 화질 70", RefOddWebp, RefOddPng), ("48×40 투명 (ALPH 거르기)", RefAlphaWebp, RefAlphaPng) })
        {
            var bytes = Convert.FromBase64String(webp);
            var me = WebP.DecodeFrames(bytes)[0].img;
            string tmp = Path.Combine(outDir, "ref_" + name.Split(' ')[0] + ".png");
            File.WriteAllBytes(tmp, Convert.FromBase64String(png));
            var r = LoadPng(tmp);
            bool aok = r.W == me.W && r.H == me.H;
            for (int i = 0; aok && i < r.P.Length; i++) if ((r.P[i] >> 24) != (me.P[i] >> 24)) aok = false;
            double ps = aok ? PsnrY(r, me, true) : 0;
            Ok(aok && ps > 55, $"libwebp 가 만든 손실 WebP {name}: 알파 같음 {aok}, libwebp 로 푼 것과 밝기 PSNR {ps:0.0}dB");
        }
    }
}
